homepageCSS:
@import url('https://fonts.googleapis.com/css2?family=Fraunces:opsz,wght@9..144,400;9..144,500;9..144,600;9..144,800&family=Newsreader:ital,opsz,wght@0,6..72,400;0,6..72,500;1,6..72,400&display=swap');

:root {
  --leaf-deep: oklch(38% 0.06 145);
  --leaf: oklch(46% 0.085 145);
  --leaf-mid: oklch(58% 0.09 142);
  --leaf-soft: oklch(72% 0.07 138);
  --cream: oklch(96% 0.018 95);
  --cream-warm: oklch(92% 0.035 88);
  --paper: oklch(98% 0.012 95);
  --ink: oklch(22% 0.025 145);
  --ink-soft: oklch(34% 0.03 145);
  --monarch: oklch(68% 0.18 50);
  --monarch-deep: oklch(56% 0.19 42);
  --milkweed: oklch(86% 0.04 100);

  --space-2xs: 4px;
  --space-xs: 8px;
  --space-sm: 12px;
  --space-md: 16px;
  --space-lg: 24px;
  --space-xl: 32px;
  --space-2xl: 48px;
  --space-3xl: 64px;
  --space-4xl: 96px;

  --display: 'Fraunces', Georgia, serif;
  --body: 'Newsreader', Georgia, serif;

  --ease-out: cubic-bezier(0.25, 1, 0.5, 1);
}

* { margin: 0; padding: 0; box-sizing: border-box; }

html { scroll-behavior: smooth; }

body {
  font-family: var(--body);
  font-size: 18px;
  line-height: 1.55;
  color: var(--ink);
  background: var(--cream);
  font-kerning: normal;
  -webkit-font-smoothing: antialiased;
  overflow-x: hidden;
}

img { max-width: 100%; display: block; }

/* NAV */
.nav {
  position: fixed;
  top: 0; left: 0; right: 0;
  z-index: 100;
  padding: var(--space-md) var(--space-2xl);
  display: flex;
  justify-content: space-between;
  align-items: center;
  background: oklch(96% 0.018 95 / 0.92);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border-bottom: 1px solid oklch(46% 0.085 145 / 0.12);
}

.brand {
  display: flex;
  align-items: center;
  gap: var(--space-sm);
  font-family: var(--display);
  font-weight: 600;
  font-size: 20px;
  color: var(--leaf-deep);
  letter-spacing: -0.01em;
  text-decoration: none;
}

.brand-mark {
  width: 36px;
  height: 36px;
  display: grid;
  place-items: center;
  color: var(--monarch);
}

.brand-mark svg { width: 100%; height: 100%; }

.brand small {
  display: block;
  font-family: var(--body);
  font-size: 11px;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--leaf-mid);
  font-weight: 500;
  margin-top: 2px;
}

.nav-links {
  display: flex;
  gap: var(--space-xl);
  align-items: center;
  list-style: none;
}

.nav-links a {
  color: var(--ink-soft);
  text-decoration: none;
  font-size: 15px;
  font-weight: 500;
  transition: color 150ms var(--ease-out);
}

.nav-links a:hover { color: var(--leaf-deep); }
.nav-links a:focus-visible { outline: 2px solid var(--leaf); outline-offset: 4px; border-radius: 2px; }

.nav-cta {
  background: var(--monarch-deep);
  color: var(--cream);
  padding: 10px 18px;
  border-radius: 999px;
  font-size: 14px;
  font-weight: 500;
  transition: transform 150ms var(--ease-out), background 150ms var(--ease-out);
}
.nav-cta:hover { background: var(--ink); color: var(--cream) !important; transform: translateY(-1px); }

/* HERO */
.hero {
  padding: 140px var(--space-2xl) var(--space-3xl);
  position: relative;
  overflow: hidden;
  background:
    radial-gradient(ellipse at 80% 10%, oklch(72% 0.07 138 / 0.35), transparent 55%),
    radial-gradient(ellipse at 10% 90%, oklch(86% 0.04 100 / 0.5), transparent 50%),
    var(--cream);
}

.hero-grid {
  max-width: 1320px;
  margin: 0 auto;
  display: grid;
  grid-template-columns: 1.1fr 1fr;
  gap: var(--space-3xl);
  align-items: center;
}

.eyebrow {
  display: inline-flex;
  align-items: center;
  gap: var(--space-sm);
  font-size: 12px;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--leaf);
  font-weight: 500;
  margin-bottom: var(--space-lg);
  opacity: 0;
  animation: fadeUp 600ms var(--ease-out) 100ms forwards;
}
.eyebrow::before {
  content: "";
  width: 32px;
  height: 1px;
  background: var(--leaf);
}

.hero h1 {
  font-family: var(--display);
  font-weight: 500;
  font-size: clamp(44px, 6.2vw, 88px);
  line-height: 0.98;
  letter-spacing: -0.025em;
  color: var(--ink);
  margin-bottom: var(--space-lg);
  font-variation-settings: "opsz" 144, "SOFT" 50;
  opacity: 0;
  animation: fadeUp 700ms var(--ease-out) 200ms forwards;
}

.hero h1 em {
  font-style: italic;
  font-weight: 400;
  color: var(--monarch-deep);
  font-variation-settings: "opsz" 144, "SOFT" 100;
}

.hero-sub {
  font-size: 20px;
  line-height: 1.5;
  color: var(--ink-soft);
  max-width: 520px;
  margin-bottom: var(--space-2xl);
  opacity: 0;
  animation: fadeUp 700ms var(--ease-out) 320ms forwards;
}

.cta-row {
  display: flex;
  gap: var(--space-md);
  align-items: center;
  flex-wrap: wrap;
  margin-bottom: var(--space-lg);
  opacity: 0;
  animation: fadeUp 700ms var(--ease-out) 440ms forwards;
}

.btn {
  display: inline-flex;
  align-items: center;
  gap: var(--space-sm);
  padding: 16px 28px;
  border-radius: 4px;
  font-family: var(--body);
  font-size: 16px;
  font-weight: 500;
  text-decoration: none;
  cursor: pointer;
  border: none;
  transition: transform 150ms var(--ease-out), background 150ms var(--ease-out), box-shadow 200ms var(--ease-out);
  min-height: 48px;
}

.btn-primary {
  background: var(--monarch-deep);
  color: var(--cream);
  box-shadow: 0 1px 0 oklch(40% 0.18 42), 0 8px 24px -8px oklch(56% 0.19 42 / 0.5);
}
.btn-primary:hover {
  background: var(--ink);
  transform: translateY(-2px);
  box-shadow: 0 1px 0 var(--ink), 0 12px 28px -8px oklch(22% 0.025 145 / 0.4);
}
.btn-primary:focus-visible {
  outline: 3px solid var(--leaf);
  outline-offset: 3px;
}

.btn-secondary {
  background: transparent;
  color: var(--ink);
  border: 1px solid oklch(34% 0.03 145 / 0.3);
}
.btn-secondary:hover { border-color: var(--ink); background: oklch(46% 0.085 145 / 0.06); }
.btn-secondary:focus-visible { outline: 3px solid var(--leaf); outline-offset: 3px; }

.btn-arrow {
  display: inline-block;
  transition: transform 200ms var(--ease-out);
}
.btn:hover .btn-arrow { transform: translateX(4px); }

.micro {
  font-size: 14px;
  color: var(--leaf);
  opacity: 0;
  animation: fadeUp 700ms var(--ease-out) 560ms forwards;
}

.trust {
  margin-top: var(--space-2xl);
  display: flex;
  align-items: center;
  gap: var(--space-lg);
  padding-top: var(--space-lg);
  border-top: 1px solid oklch(46% 0.085 145 / 0.15);
  opacity: 0;
  animation: fadeUp 700ms var(--ease-out) 680ms forwards;
}

.cert-badge {
  width: 56px;
  height: 56px;
  border-radius: 50%;
  background: var(--leaf-deep);
  color: var(--cream);
  display: grid;
  place-items: center;
  font-family: var(--display);
  font-size: 11px;
  text-align: center;
  line-height: 1.1;
  font-weight: 600;
  flex-shrink: 0;
  letter-spacing: 0.05em;
}

.trust-text {
  font-size: 14px;
  color: var(--ink-soft);
  line-height: 1.4;
}
.trust-text strong { color: var(--leaf-deep); font-weight: 600; display: block; }

/* HERO VISUAL */
.hero-visual {
  position: relative;
  height: 600px;
  opacity: 0;
  animation: fadeIn 900ms var(--ease-out) 400ms forwards;
}

.hero-img-main {
  position: absolute;
  top: 0; right: 0;
  width: 78%;
  height: 78%;
  object-fit: cover;
  border-radius: 200px 200px 8px 8px;
  filter: saturate(1.05);
}

.hero-img-accent {
  position: absolute;
  bottom: 0; left: 0;
  width: 52%;
  height: 42%;
  object-fit: cover;
  border-radius: 8px 8px 8px 120px;
  border: 8px solid var(--cream);
}

.hero-stat {
  position: absolute;
  top: 32%;
  left: 8%;
  background: var(--cream);
  padding: var(--space-md) var(--space-lg);
  border-radius: 4px;
  box-shadow: 0 12px 32px -12px oklch(22% 0.025 145 / 0.25);
  z-index: 3;
}

.hero-stat .num {
  font-family: var(--display);
  font-size: 38px;
  font-weight: 500;
  color: var(--monarch-deep);
  line-height: 1;
  font-variant-numeric: tabular-nums;
}
.hero-stat .lbl {
  font-size: 12px;
  color: var(--ink-soft);
  letter-spacing: 0.1em;
  text-transform: uppercase;
  margin-top: 4px;
}

/* MISSION */
.mission {
  padding: var(--space-4xl) var(--space-2xl);
  background: var(--leaf-deep);
  color: var(--cream);
  position: relative;
}

.mission-inner {
  max-width: 1100px;
  margin: 0 auto;
  display: grid;
  grid-template-columns: 1fr 1.5fr;
  gap: var(--space-3xl);
  align-items: start;
}

.section-label {
  font-size: 12px;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  color: var(--leaf-soft);
  font-weight: 500;
  margin-bottom: var(--space-md);
}

.mission .section-label { color: var(--leaf-soft); }

.mission h2 {
  font-family: var(--display);
  font-size: clamp(32px, 4vw, 52px);
  font-weight: 400;
  line-height: 1.05;
  letter-spacing: -0.02em;
  font-variation-settings: "opsz" 144, "SOFT" 50;
}
.mission h2 em {
  font-style: italic;
  color: var(--monarch);
  font-weight: 400;
}

.mission-body p {
  font-size: 19px;
  line-height: 1.6;
  color: oklch(92% 0.02 95);
  margin-bottom: var(--space-md);
}
.mission-body p:first-child::first-letter {
  font-family: var(--display);
  font-size: 64px;
  float: left;
  line-height: 0.85;
  margin: 6px 12px 0 0;
  color: var(--monarch);
  font-weight: 500;
}

/* HIGHLIGHTS */
.highlights {
  padding: var(--space-4xl) var(--space-2xl);
  background: var(--cream);
}

.highlights .section-label { color: var(--leaf); }

.highlights-head {
  max-width: 1320px;
  margin: 0 auto var(--space-3xl);
  display: flex;
  justify-content: space-between;
  align-items: end;
  gap: var(--space-2xl);
  flex-wrap: wrap;
}

.highlights-head h2 {
  font-family: var(--display);
  font-size: clamp(36px, 4.5vw, 60px);
  font-weight: 500;
  line-height: 1;
  letter-spacing: -0.025em;
  color: var(--ink);
  max-width: 700px;
}
.highlights-head h2 em { font-style: italic; color: var(--leaf); font-weight: 400; }

.highlights-head p {
  font-size: 17px;
  color: var(--ink-soft);
  max-width: 320px;
}

.timeline {
  max-width: 1320px;
  margin: 0 auto;
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-xl);
}

.month {
  position: relative;
}

.month-img {
  width: 100%;
  aspect-ratio: 4/3;
  object-fit: cover;
  border-radius: 4px;
  margin-bottom: var(--space-md);
  transition: transform 400ms var(--ease-out);
}
.month:hover .month-img { transform: scale(1.02); }

.month-meta {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  margin-bottom: var(--space-xs);
}

.month-num {
  font-family: var(--display);
  font-size: 13px;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--leaf);
  font-weight: 500;
  font-variant-numeric: tabular-nums;
}

.month-tag {
  font-size: 13px;
  color: var(--ink-soft);
  font-style: italic;
}

.month h3 {
  font-family: var(--display);
  font-size: 28px;
  font-weight: 500;
  letter-spacing: -0.015em;
  color: var(--ink);
  margin-bottom: var(--space-sm);
  line-height: 1.05;
}

.month p {
  font-size: 16px;
  line-height: 1.55;
  color: var(--ink-soft);
}

/* KITS */
.kits {
  padding: var(--space-4xl) var(--space-2xl);
  background: var(--milkweed);
  position: relative;
  overflow: hidden;
}

.kits::before {
  content: "";
  position: absolute;
  inset: 0;
  background:
    radial-gradient(circle at 90% 20%, oklch(68% 0.18 50 / 0.12), transparent 40%),
    radial-gradient(circle at 5% 80%, oklch(46% 0.085 145 / 0.1), transparent 45%);
  pointer-events: none;
}

.kits .section-label { color: var(--leaf); }

.kits-inner {
  max-width: 1320px;
  margin: 0 auto;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--space-3xl);
  align-items: center;
  position: relative;
}

.kits-text h2 {
  font-family: var(--display);
  font-size: clamp(40px, 5vw, 68px);
  font-weight: 500;
  line-height: 1;
  letter-spacing: -0.025em;
  color: var(--ink);
  margin: var(--space-md) 0 var(--space-lg);
}
.kits-text h2 em { font-style: italic; color: var(--monarch-deep); font-weight: 400; }

.kits-text > p {
  font-size: 18px;
  line-height: 1.6;
  color: var(--ink-soft);
  margin-bottom: var(--space-xl);
  max-width: 520px;
}

.kit-features {
  list-style: none;
  display: grid;
  gap: 0;
  margin-bottom: var(--space-2xl);
}

.kit-features li {
  display: flex;
  gap: var(--space-md);
  align-items: start;
  padding: var(--space-md) 0;
  border-top: 1px solid oklch(46% 0.085 145 / 0.18);
  font-size: 16px;
}
.kit-features li:last-child { border-bottom: 1px solid oklch(46% 0.085 145 / 0.18); }

.kit-features .num {
  font-family: var(--display);
  font-variant-numeric: tabular-nums;
  font-size: 14px;
  color: var(--leaf);
  font-weight: 500;
  letter-spacing: 0.05em;
  flex-shrink: 0;
  width: 32px;
  padding-top: 2px;
}

.kit-features strong {
  font-weight: 600;
  color: var(--ink);
  display: block;
  margin-bottom: 2px;
}
.kit-features span { color: var(--ink-soft); font-size: 15px; }

.kits-visual {
  position: relative;
  aspect-ratio: 4/5;
}

.kits-img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  border-radius: 8px;
}

.float-card {
  position: absolute;
  bottom: -24px;
  left: -24px;
  background: var(--leaf-deep);
  color: var(--cream);
  padding: var(--space-lg) var(--space-xl);
  border-radius: 4px;
  max-width: 240px;
  box-shadow: 0 16px 40px -16px oklch(22% 0.025 145 / 0.4);
}
.float-card .price {
  font-family: var(--display);
  font-size: 32px;
  font-weight: 500;
  font-variant-numeric: tabular-nums;
  display: block;
  margin-bottom: var(--space-2xs);
}
.float-card p { font-size: 13px; color: oklch(88% 0.025 95); line-height: 1.4; }

/* ABOUT */
.about {
  padding: var(--space-4xl) var(--space-2xl);
  background: var(--cream);
}

.about .section-label { color: var(--leaf); }

.about-inner {
  max-width: 1100px;
  margin: 0 auto;
  display: grid;
  grid-template-columns: 0.9fr 1.1fr;
  gap: var(--space-3xl);
  align-items: center;
}

.about-img {
  aspect-ratio: 3/4;
  object-fit: cover;
  border-radius: 4px;
  width: 100%;
}

.about h2 {
  font-family: var(--display);
  font-size: clamp(36px, 4.5vw, 56px);
  font-weight: 500;
  line-height: 1;
  letter-spacing: -0.025em;
  margin: var(--space-md) 0 var(--space-lg);
}
.about h2 em { font-style: italic; color: var(--monarch-deep); font-weight: 400; }

.about p {
  font-size: 18px;
  line-height: 1.65;
  color: var(--ink-soft);
  margin-bottom: var(--space-md);
}

.signature {
  margin-top: var(--space-xl);
  padding-top: var(--space-lg);
  border-top: 1px solid oklch(46% 0.085 145 / 0.18);
  font-family: var(--display);
  font-style: italic;
  font-size: 22px;
  color: var(--leaf-deep);
}
.signature small {
  display: block;
  font-family: var(--body);
  font-style: normal;
  font-size: 13px;
  color: var(--ink-soft);
  letter-spacing: 0.1em;
  text-transform: uppercase;
  margin-top: 4px;
}

/* CTA FOOTER */
.cta-final {
  padding: var(--space-4xl) var(--space-2xl);
  background: var(--ink);
  color: var(--cream);
  position: relative;
  overflow: hidden;
}

.cta-final::before {
  content: "";
  position: absolute;
  inset: 0;
  background:
    radial-gradient(ellipse at 30% 50%, oklch(56% 0.19 42 / 0.18), transparent 50%),
    radial-gradient(ellipse at 80% 80%, oklch(46% 0.085 145 / 0.25), transparent 50%);
}

.cta-inner {
  max-width: 1100px;
  margin: 0 auto;
  position: relative;
  text-align: center;
}

.cta-final h2 {
  font-family: var(--display);
  font-size: clamp(40px, 6vw, 80px);
  font-weight: 400;
  line-height: 1;
  letter-spacing: -0.03em;
  margin-bottom: var(--space-lg);
  font-variation-settings: "opsz" 144, "SOFT" 80;
}
.cta-final h2 em { font-style: italic; color: var(--monarch); }

.cta-final p {
  font-size: 19px;
  color: oklch(86% 0.02 95);
  max-width: 560px;
  margin: 0 auto var(--space-2xl);
  line-height: 1.5;
}

footer {
  background: var(--ink);
  color: oklch(78% 0.02 145);
  padding: var(--space-2xl);
  border-top: 1px solid oklch(34% 0.03 145);
  font-size: 14px;
  text-align: center;
}
footer .brand { color: var(--cream); justify-content: center; margin-bottom: var(--space-md); }

/* ANIMATIONS */
@keyframes fadeUp {
  from { opacity: 0; transform: translateY(20px); }
  to { opacity: 1; transform: translateY(0); }
}
@keyframes fadeIn {
  from { opacity: 0; }
  to { opacity: 1; }
}

.reveal {
  opacity: 0;
  transform: translateY(24px);
  transition: opacity 700ms var(--ease-out), transform 700ms var(--ease-out);
}
.reveal.in {
  opacity: 1;
  transform: translateY(0);
}

/* RESPONSIVE */
@media (max-width: 900px) {
  .hero { padding: 110px var(--space-lg) var(--space-2xl); }
  .hero-grid, .mission-inner, .kits-inner, .about-inner {
    grid-template-columns: 1fr;
    gap: var(--space-2xl);
  }
  .hero-visual { height: 460px; }
  .timeline { grid-template-columns: 1fr; gap: var(--space-2xl); }
  .nav { padding: var(--space-sm) var(--space-md); }
  .nav-links { gap: var(--space-md); }
  .nav-links a:not(.nav-cta) { display: none; }
  .brand { font-size: 16px; }
  .brand small { font-size: 10px; }
  .mission, .highlights, .kits, .about, .cta-final { padding: var(--space-3xl) var(--space-md); }
  .hero-stat { left: auto; right: 8%; top: 28%; }
  .float-card { left: var(--space-md); bottom: -16px; }
  .highlights-head { flex-direction: column; align-items: start; }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
  .reveal { opacity: 1; transform: none; }
  html { scroll-behavior: auto; }
}
